	/** 
	 * jumpstart the process by instantiating2 Bank
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		bankId = BankService.getBankInstance()
		.createBank( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		BankService.getBankInstance()
				.createBank( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.bankSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Bank : " + successValue.getBankId());
							  if (successValue.getBankId().equals(bankId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfBankList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Bank test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on bank consumed")
					);
			subscriber.bankSubscribe( bankId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Bank : " + successValue.getBankId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfBankList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on bank for bankId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Bank. 
	 */
	protected Bank read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Bank" );

		Bank entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Bank with primary key" );
		msg.append( bankId );
		
		BankFetchOneSummary fetchOneSummary = new BankFetchOneSummary( bankId );

		try {
			entity = BankService.getBankInstance().getBank( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Bank " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Bank.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Bank." );

		StringBuilder msg = new StringBuilder( "Failed to update a Bank : " );        
		Bank entity = read();
		UpdateBankCommand command = generateUpdateCommand();
		command.setBankId(entity.getBankId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Bank." );

			// for use later on...
			bankId = entity.getBankId();

			BankService proxy = BankService.getBankInstance();  

			proxy.updateBank( command ).get();

			LOGGER.info( "-- Successfully saved Bank - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + bankId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Bank.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Bank." );

		Bank entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Bank with id " + bankId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Bank with id " + bankId );

			throw e;
		}

		try{
			BankService.getBankInstance().delete( new DeleteBankCommand( entity.getBankId() ) ).get();
			LOGGER.info( "-- Successfully deleted Bank with id " + bankId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Bank with id " + bankId );

			throw e;
		}
	}

	/**
	 * get all Banks.
	 */
	protected List<Bank> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Banks:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Bank : " );        
		List<Bank> collection  = new ArrayList<>();

		try {
			// call the static get method on the BankService
			collection = BankService.getBankInstance().getAllBank();
			assertNotNull( collection, "An Empty collection of Bank was incorrectly returned.");
			
			// Now print out the values
			Bank entity = null;            
			Iterator<Bank> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getBankId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

